lines<-readLines("stdin",warn=FALSE);nm<-as.integer(strsplit(lines[1],"\\s+")[[1]]);n<-nm[1];m<-nm[2];q<-vector("list",m);for(i in 1:m){p<-strsplit(lines[i+1],"\\s+")[[1]];cnum<-as.integer(p[3]);q[[i]]<-list(score=as.numeric(p[1]),ans=p[4:(3+cnum)])};wrong<-integer(m);scores<-numeric(n);for(i in 1:n){parts<-regmatches(lines[m+1+i],gregexpr("\\([^)]*\\)",lines[m+1+i]))[[1]];for(j in 1:m){p<-strsplit(gsub("[()]","",parts[j]),"\\s+")[[1]];sel<-p[-1];if(setequal(sel,q[[j]]$ans))scores[i]<-scores[i]+q[[j]]$score else wrong[j]<-wrong[j]+1L}};cat(paste(sprintf("%.0f",scores),collapse="\n"),"\n",sep="");mx<-max(wrong);if(mx==0)cat("Too simple\n")else{qs<-which(wrong==mx);cat(mx,paste(qs,collapse=" "),"\n",sep=" ")}
